SELECT DISTINCT a.apply_id, a.apply_no, a.emp_id, a.hr_apply_type, a.hr_apply_sub_type, a.start_time, a.end_time, a.supplement_id, a.apply_day, a.apply_reason, a.main_attach_id, a.is_nurse, a.status, a.template_config_id, a.process_definition_id, a.process_instance_id, a.remark, a.create_user, a.create_time, a.update_time, COALESCE(e.emp_code, a.emp_code, '') AS emp_code, COALESCE(e.emp_name, a.emp_name, '') AS emp_name, COALESCE(e.emp_phone, a.emp_phone, '') AS emp_phone, COALESCE(e.dept_id, a.dept_id) AS dept_id, COALESCE(d.dept_name, a.dept_name, '') AS dept_name FROM hr_apply a LEFT JOIN sys_emp e ON a.emp_id = e.emp_id LEFT JOIN sys_dept d ON COALESCE(e.dept_id, a.dept_id) = d.dept_id INNER JOIN wf_process_task pt ON a.apply_no = pt.task_key WHERE pt.assignee_user_id = #{userId}
AND pt.task_status = #{status}
ORDER BY a.create_time DESC LIMIT #{offset}, #{size}

SELECT COUNT(DISTINCT a.apply_id) FROM hr_apply a INNER JOIN wf_process_task pt ON a.apply_no = pt.task_key WHERE pt.assignee_user_id = #{userId}
AND pt.task_status = #{status}
-- 加签场景：如果有加签任务（is_addsign_task=1），只显示加签任务，原任务不显示 -- 如果没有加签任务，显示原任务 AND ( pt.is_addsign_task = 1 OR NOT EXISTS ( SELECT 1 FROM wf_process_task addsign_task WHERE addsign_task.task_key = pt.task_key AND addsign_task.is_addsign_task = 1 AND addsign_task.task_status = 'PENDING' ) )

SELECT a.apply_id, a.apply_no, a.emp_id, a.hr_apply_type, a.hr_apply_sub_type, a.start_time, a.end_time, a.supplement_id, a.apply_day, a.apply_reason, a.main_attach_id, a.is_nurse, a.status, a.template_config_id, a.process_definition_id, a.process_instance_id, a.remark, a.create_user, a.create_time, a.update_time, COALESCE(e.emp_code, a.emp_code, '') AS emp_code, COALESCE(e.emp_name, a.emp_name, '') AS emp_name, COALESCE(e.emp_phone, a.emp_phone, '') AS emp_phone, COALESCE(e.dept_id, a.dept_id) AS dept_id, COALESCE(d.dept_name, a.dept_name, '') AS dept_name FROM hr_apply a LEFT JOIN sys_emp e ON a.emp_id = e.emp_id LEFT JOIN sys_dept d ON COALESCE(e.dept_id, a.dept_id) = d.dept_id WHERE 1=1
AND a.apply_no LIKE CONCAT('%', #{applyNo}, '%')
AND a.emp_id = #{empId}
AND (COALESCE(e.emp_name, a.emp_name, '') LIKE CONCAT('%', #{empName}, '%'))
AND a.hr_apply_type = #{hrApplyType}
AND a.status = #{status}
AND DATE(a.start_time) >= #{startDate}
AND DATE(a.start_time) <= #{endDate}
ORDER BY a.create_time DESC

mapper.update:
UPDATE hr_apply
emp_code = #{empCode}, emp_name = #{empName}, emp_phone = #{empPhone}, dept_id = #{deptId}, dept_name = #{deptName}, hr_apply_type = #{hrApplyType}, hr_apply_sub_type = #{hrApplySubType}, start_time = #{startTime}, end_time = #{endTime}, supplement_id = #{supplementId}, apply_day = #{applyDay}, apply_reason = #{applyReason}, main_attach_id = #{mainAttachId}, is_nurse = #{isNurse}, status = #{status}, template_config_id = #{templateConfigId}, process_definition_id = #{processDefinitionId}, process_instance_id = #{processInstanceId}, remark = #{remark},
WHERE apply_id = #{applyId}
